import attr
from attr import cached_property

@attr.s(slots=True)
class A:
    @cached_property
    def foo(self):
        return 1

a = A()
print("Testing A.bar")
try:
    print(a.bar)
except AttributeError as e:
    print(f"Caught: {e}")

